const BOZP_OFFICIAL={
 RPU_DOCX:'', OPU_DOCX:'',
 RPU_PDF:'', OPU_PDF:'',
 FONT:''
};
const BOZP_RPU_BOLD_FONT='';
function officialBase64Bytes(s){const a=atob(s),b=new Uint8Array(a.length);for(let i=0;i<a.length;i++)b[i]=a.charCodeAt(i);return b}
function officialBlobDownload(bytes,name,type){const u=URL.createObjectURL(new Blob([bytes],{type}));const l=document.createElement('a');l.href=u;l.download=name;document.body.appendChild(l);l.click();l.remove();setTimeout(()=>URL.revokeObjectURL(u),120000)}
function officialData(){const a=currentAccident(),c=company();if(!a||!c)throw Error('Vyber firmu a pracovný úraz.');const v=k=>String(a[k]??'').trim();return {
 ...a, ico:String(a.ico||c.ico||c.icoNumber||c.companyIco||a.employerIco||''), employer:[c.name,c.address].filter(Boolean).join(', '),site:v('rpuOrganizationUnit'), organizationUnit:v('rpuOrganizationUnit'), rpuOrganizationUnit:v('rpuOrganizationUnit'), workplace:v('workplace'),
 dateTime:[v('date'),v('time')].filter(Boolean).join(' / '),salaryYes:v('salaryOffice')?'ÁNO':'',
 injuryTick:'X', recognized:'ÁNO',employeeFaultPercent:v('responsibility')?String(100-Number(v('responsibility'))):'',
 source:[v('source'),a.sourceCode?'('+a.sourceCode+')':''].filter(Boolean).join(' '),
 cause:[v('cause'),a.causeCode?'('+a.causeCode+')':''].filter(Boolean).join(' '),
 injury:v('injury')||accidentCodeLabel('injuryCode',v('injuryCode')),
 contact:v('contact'), accidentNumber:v('accidentNumber'),occupationCode:v('occupationCode'),age:v('age'),gender:v('gender'),regionCode:v('regionCode'),organizationSize:v('organizationSize'),citizenshipCode:v('citizenshipCode'),workplaceSpec:v('workplaceSpec'),workplaceCode:v('workplaceCode'),signaturePlace:'',knowledgeChecked:'',
 } }
function officialXmlEsc(s){return String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&apos;')}
async function officialWord(kind){
 const d=officialData(),data=officialBase64Bytes(kind==='rpu'?BOZP_OFFICIAL.RPU_DOCX:BOZP_OFFICIAL.OPU_DOCX);
 const zip=await JSZip.loadAsync(data);const part='word/document.xml';let xml=await zip.file(part).async('string');
 // Replace exact placeholder text nodes only; untouched OOXML remains as in the original official document.
 xml=xml.replace(/⟦([A-Za-z][A-Za-z0-9]*)⟧/g,(m,k)=>officialXmlEsc(d[k]??''));
 zip.file(part,xml);const out=await zip.generateAsync({type:'uint8array',compression:'DEFLATE'});
 officialBlobDownload(out,(kind==='rpu'?'Zaznam_RPU':'Oznamenie_poistnej_udalosti')+'_'+(d.date||'bez_datumu')+'.docx','application/vnd.openxmlformats-officedocument.wordprocessingml.document');
}
// Uchovaj cely text aj v pripade, ze je dlhy na predtlacene pole.
let bozpPdfTextAnnex=[];
function bozpPdfWrap(font,str,size,w){
 const out=[];for(const paragraph of String(str).split(/\n/)){
  if(!paragraph.trim()){out.push('');continue;}
  let line='';for(const word of paragraph.trim().split(/\s+/)){
   const candidate=line?line+' '+word:word;
   if(line&&font.widthOfTextAtSize(candidate,size)>w){out.push(line);line=word;}else line=candidate;
   // Long unbroken entries (e.g. identifiers) must fit without overflowing the border.
   while(line&&font.widthOfTextAtSize(line,size)>w){
     let split=1;while(split<line.length&&font.widthOfTextAtSize(line.slice(0,split+1),size)<=w)split++;
     out.push(line.slice(0,split));line=line.slice(split);
   }
  }if(line)out.push(line);
 }return out;
}
function bozpPdfFitted(page,font,value,x,top,w,maxLines,size,upper=false){
 const original=String(value??'').trim();if(!original)return;
 const str=upper?original.toLocaleUpperCase('sk-SK'):original;
 const safeWidth=Math.max(8,Number(w)||150), linesLimit=Math.max(1,Number(maxLines)||1);
 let chosen=null, chosenSize=Number(size)||8;
 // Real text fitting: do not replace the value with an annex label.
 for(let z=chosenSize;z>=1;z=Math.round((z-.1)*10)/10){
   const lines=linesLimit===1?[str.replace(/\s+/g,' ')]:bozpPdfWrap(font,str,z,safeWidth);
   if(lines.length<=linesLimit && lines.every(line=>font.widthOfTextAtSize(line,z)<=safeWidth+0.01)){
     chosen=lines; chosenSize=z; break;
   }
 }
 if(!chosen){
   const normalized=str.replace(/\s+/g,' ');
   chosen=[normalized];
   chosenSize=Math.min(1,Math.max(.15,safeWidth/Math.max(font.widthOfTextAtSize(normalized,1),.001)));
 }
 const H=page.getSize().height,step=Math.min(chosenSize+2,Math.max(2,chosenSize*1.2));
 chosen.forEach((line,i)=>page.drawText(line,{x,y:H-top-i*step,size:chosenSize,font,color:PDFLib.rgb(.04,.12,.23)}));
}
function officialWrite(page,font,value,x,top,w=150,maxLines=1,size=8){
 return bozpPdfFitted(page,font,value,x,top,w,maxLines,size,false);
}
async function bozpPdfAddAnnex(pdf,font){
 if(!bozpPdfTextAnnex.length)return;
 const items=bozpPdfTextAnnex.slice();let page=null,y=0;
 function newPage(){page=pdf.addPage([595,842]);y=795;page.drawText('PRÍLOHA – POKRAČOVANIE ÚDAJOV K PRACOVNÉMU ÚRAZU',{x:40,y,size:11,font,color:PDFLib.rgb(.06,.13,.22)});y-=34;}
 newPage();
 for(const item of items){
  const caption='Položka '+item.index+' – úplný text:';
  if(y<95)newPage();page.drawText(caption,{x:40,y,size:9,font});y-=15;
  const lines=bozpPdfWrap(font,item.text,8,505);
  for(const line of lines){if(y<52)newPage();if(line)page.drawText(line,{x:40,y,size:8,font});y-=12;}
  y-=14;
 }
}

function officialDigits(page,font,value,x,top,step,count,size=8){
 const str=String(value??'').replace(/[^0-9]/g,'');if(!str)return;
 if(str.length>count)throw Error('Číslo '+str+' má viac číslic, než obsahuje úradné tlačivo.');
 const H=page.getSize().height;
 for(let i=0;i<str.length;i++){const c=str[i];const cw=font.widthOfTextAtSize(c,size);page.drawText(c,{x:x+i*step+(step-cw)/2,y:H-top,size,font,color:PDFLib.rgb(0.04,0.12,0.23)});}
}
