function rpuCap(v){return String(v??'').trim().replace(/\s+/g,' ').toLocaleUpperCase('sk-SK')}
function rpuISODate(v){let x=String(v||'').trim();let m=x.match(/^(\d{4})-(\d{2})-(\d{2})$/);return m?m[1]+m[2]+m[3]:x.replace(/[^0-9]/g,'')}
function rpuAge(birth,date){if(!birth||!date)return '';const b=new Date(birth),d=new Date(date);if(!Number.isFinite(b.getTime())||!Number.isFinite(d.getTime()))return '';return String(d.getFullYear()-b.getFullYear()-(d.getMonth()<b.getMonth()||(d.getMonth()===b.getMonth()&&d.getDate()<b.getDate())?1:0));}
function rpuSplitShift(a){let from=String(a.shiftStart||'').trim(),to=String(a.shiftEnd||'').trim();if(!from||!to){const parts=String(a.shift||'').match(/\d{1,2}:\d{2}/g)||[];from=from||parts[0]||'';to=to||parts[1]||'';}return [from,to];}
function rpuDuration(a){let y=String(a.durationYears??'').trim(),m=String(a.durationMonths??'').trim(),day=String(a.durationDays??'').trim();if(!y&&!m&&!day){let inp=String(a.workDuration||'').trim(),xs=inp.match(/\d+/g)||[];if(xs.length===3)[y,m,day]=xs;}return [y,m,day];}
function rpuText(page,font,value,x,top,w,maxLines=1,size=9.0,upper=true){
 return bozpPdfFitted(page,font,value,x,top,w,maxLines,size,upper);
}
function rpuCells(page,font,v,xs,top,size=9.0){
 const raw=String(v??'').toLocaleUpperCase('sk').replace(/[^0-9A-Z]/g,'');if(!raw)return;
 if(raw.length>xs.length)throw Error('Kód '+raw+' má '+raw.length+' znakov, ale vo formulári je iba '+xs.length+' políčok.');
 const y=page.getSize().height-top;
 for(let i=0;i<raw.length;i++){const c=raw[i],cx=xs[i];page.drawText(c,{x:cx-font.widthOfTextAtSize(c,size)/2,y,size,font,color:PDFLib.rgb(0.03,0.03,0.04)});}
}
