function bozpParseISODate(value){
 if(!/^\d{4}-\d{2}-\d{2}$/.test(String(value||'')))return null;
 const [y,m,d]=value.split('-').map(Number),dt=new Date(Date.UTC(y,m-1,d));
 return dt.getUTCFullYear()===y&&dt.getUTCMonth()===m-1&&dt.getUTCDate()===d?dt:null;
}
function bozpPlusMonthsClamped(start,howMany){
 const y=start.getUTCFullYear(),m=start.getUTCMonth(),d=start.getUTCDate();
 const target=new Date(Date.UTC(y,m+howMany,1));
 const finalDay=Math.min(d,new Date(Date.UTC(target.getUTCFullYear(),target.getUTCMonth()+1,0)).getUTCDate());
 return new Date(Date.UTC(target.getUTCFullYear(),target.getUTCMonth(),finalDay));
}
function bozpTenure(startValue,endValue){
 const start=bozpParseISODate(startValue),end=bozpParseISODate(endValue);
 if(!start||!end)return null;
 if(start>end)return {invalid:true,years:0,months:0,days:0};
 let fullMonths=(end.getUTCFullYear()-start.getUTCFullYear())*12+end.getUTCMonth()-start.getUTCMonth();
 while(fullMonths>0&&bozpPlusMonthsClamped(start,fullMonths)>end)fullMonths--;
 while(bozpPlusMonthsClamped(start,fullMonths+1)<=end)fullMonths++;
 const anchor=bozpPlusMonthsClamped(start,fullMonths);
 return {invalid:false,years:Math.floor(fullMonths/12),months:fullMonths%12,days:Math.round((end-anchor)/86400000)};
}
const bozpOriginalAccidentSet=accidentSet;
accidentSet=function(key,value){
 bozpOriginalAccidentSet(key,value);
 if(key==='hireDate'||key==='date'||key==='birth'){
  const a=currentAccident()||{},result=bozpTenure(a.hireDate,a.date);
  const target=document.getElementById('bozpTenureFeedback');
  if(target)target.innerHTML=bozpTenureHTML(a);
  const ageElement=document.getElementById('bozpAgeFeedback');
  if(ageElement)ageElement.textContent=a.birth&&a.date?'Vek v deň úrazu: '+(rpuAge(a.birth,a.date)||'—')+' rokov':'Vek sa vypočíta z dátumu narodenia a dátumu úrazu.';
 }
};
function bozpSlovakUnit(n,one,few,many){return n===1?one:(n>=2&&n<=4?few:many);}
function bozpTenureHTML(a){
 const d=bozpTenure(a.hireDate,a.date);
 if(!a.hireDate)return 'Zadaj dátum nástupu na vykonávanú funkciu.';
 if(!a.date)return 'Zadaj aj dátum úrazu – potom sa dĺžka práce vypočíta automaticky.';
 if(!d)return 'Dátum nie je platný.';
 if(d.invalid)return '<b style="color:#b42318">Dátum nástupu nesmie byť po dátume úrazu.</b>';
 return '<b style="color:#126450">Automaticky: '+d.years+' '+bozpSlovakUnit(d.years,'rok','roky','rokov')+' · '+d.months+' '+bozpSlovakUnit(d.months,'mesiac','mesiace','mesiacov')+' · '+d.days+' '+bozpSlovakUnit(d.days,'deň','dni','dní')+'</b> (k dátumu úrazu)';
}
const bozpPrevRpuDuration=rpuDuration;
rpuDuration=function(a){
 if(a.hireDate){
  const span=bozpTenure(a.hireDate,a.date);
  if(!span||span.invalid)throw Error('Dátum nástupu na funkciu musí byť platný a nesmie byť po dátume úrazu.');
  return [String(span.years),String(span.months),String(span.days)];
 }
 return bozpPrevRpuDuration(a);
};
// Zoskupenie polí: dátum nástupu a číselník povolania sa uvádzajú pri osobných údajoch.
function bozpMoveAccidentField(key,from,to,after,overrideLabel,overrideType){
 let arr=accidentSections[from][1],index=arr.findIndex(x=>x[0]===key);
 if(index<0)return;
 let item=arr.splice(index,1)[0];
 if(overrideLabel)item[1]=overrideLabel;
 if(overrideType)item[2]=overrideType;
 let dest=accidentSections[to][1],target=dest.findIndex(x=>x[0]===after);
 dest.splice(target<0?dest.length:target+1,0,item);
}
