// Kontrola preklepov v kóde a dátume tiež pred otvorením náhľadu / sťahovaním.
const bozpPreviousOfficialExport=officialExport;
officialExport=async function(kind,format){
 const a=currentAccident()||{};
 if(kind==='rpu'&&a.occupationCode&&!/^\d{7}$/.test(String(a.occupationCode))){alert('Kód povolania musí obsahovať presne sedem číslic.');return;}
 if(kind==='rpu'&&a.hireDate){const span=bozpTenure(a.hireDate,a.date);if(!span||span.invalid){alert('Skontroluj dátum nástupu na funkciu a dátum úrazu.');return;}}
 return bozpPreviousOfficialExport(kind,format);
};


/* Vylepšenie OPU: výber typu udalosti a evidencie miezd, jedno písmo pri exporte. */
(function(){
  const beginning=accidentSections[0][1];
  if(!beginning.some(row=>row[0]==='eventType'))beginning.splice(1,0,['eventType','Poistná udalosť – vyber možnosť']);
  if(!beginning.some(row=>row[0]==='salaryLedger')){
    const salaryAt=beginning.findIndex(row=>row[0]==='salaryOffice');
    beginning.splice(salaryAt>=0?salaryAt:beginning.length,0,['salaryLedger','Evidenciu miezd vedie zodpovedný zamestnávateľ']);
  }
  BOZP_SELECT_FIELDS.eventType=[
    ['','— vyber —'],['pracovny_uraz','Pracovný úraz'],['choroba_z_povolania','Choroba z povolania']
  ];
  BOZP_SELECT_FIELDS.salaryLedger=[
    ['','— vyber —'],['ANO','ÁNO – zamestnávateľ vedie evidenciu miezd'],['NIE','NIE – evidenciu miezd vedie iný útvar/subjekt']
  ];
  const fieldBefore=accidentField;
  accidentField=function(key,label,type){
    if(key==='eventType'||key==='salaryLedger'){
      const a=currentAccident()||{};
      const isEvent=key==='eventType';
      const opts=isEvent?BOZP_SELECT_FIELDS.eventType.filter(t=>t[0]):BOZP_SELECT_FIELDS.salaryLedger.filter(t=>t[0]);
      const val=String(a[key]||(isEvent?'pracovny_uraz':''));
      return '<div class="field"><label>'+esc(label)+'</label><div class="bozp-choice-row" role="radiogroup" aria-label="'+esc(label)+'">'+
        opts.map(([code,text])=>'<label class="bozp-choice'+(val===code?' bozp-chosen':'')+'"><input type="radio" name="bozp_'+key+'" value="'+esc(code)+'" '+(val===code?'checked ':'')+'onchange="accidentSet(\''+key+'\',this.value);document.querySelectorAll(\'input[name=bozp_'+key+']\').forEach(el=>el.closest(\'.bozp-choice\').classList.toggle(\'bozp-chosen\',el.checked))">'+esc(text)+'</label>').join('')+'</div></div>';
    }
    return fieldBefore(key,label,type);
  };
  const dataBefore=officialData;
  officialData=function(){
    const d=dataBefore(),a=currentAccident()||{};
    d.eventType=a.eventType||'pracovny_uraz';
    d.salaryLedger=a.salaryLedger||'';
    d.salaryYes=''; // Odpoveď sa vyznačuje priamo pri ÁNO – NIE, nie v bodkovanom poli.
    d.injuryTick=''; // Krížik sa kreslí do pôvodného štvorčeka.
    return d;
  };

  // PDF vychádza z pôvodného podkladu a nemení predtlačené texty, tabuľky ani rozloženie.
  async function opuExactPDF(preview){
    if(!window.PDFLib||!window.fontkit)throw Error('Chýbajú knižnice pre vytvorenie PDF. Skontroluj internetové pripojenie.');
    const d=officialData();
    if(!['ANO','NIE'].includes(d.salaryLedger))throw Error('V základných údajoch vyber, kto vedie evidenciu miezd (ÁNO/NIE).');
    const pdf=await PDFLib.PDFDocument.load(officialBase64Bytes(BOZP_OFFICIAL.OPU_PDF));
    pdf.registerFontkit(window.fontkit);
    // ROVNAKÉ písmo použité aj v RPU: DejaVu Sans Bold, plne podporuje diakritiku.
    const font=await pdf.embedFont(officialBase64Bytes(BOZP_RPU_BOLD_FONT),{subset:false});
    const pages=pdf.getPages(), P=pages[0], H=P.getSize().height;
    const black=PDFLib.rgb(0.02,0.02,0.03),white=PDFLib.rgb(1,1,1);
    const W=(p,k,x,top,width=150,lines=1,size=8)=>officialWrite(pages[p],font,d[k],x,top,width,lines,size);
    const dotRanges=[
      [[257,211,327],[435,211,515],[310,233,517],[356,254,518],[154,291,520],[374,330,439],[449,330,494],[399,371,518],[96,392,517],[296,412,518],[260,433,515],[89,454,518],[279,474,516],[411,495,518],[314,516,519],[93,584,519]],
      [[336,79,518],[96,122,517],[167,164,518],[96,207,517],[446,223,519],[96,240,520],[445,267,519],[281,283,520],[371,299,521],[329,316,519],[280,370,519],[96,413,515],[364,434,516],[96,456,512],[240,524,484],[248,561,517]]
    ];
    for(let ip=0;ip<2;ip++)for(const [x,y,x2] of dotRanges[ip])pages[ip].drawRectangle({x:x-1,y:pages[ip].getSize().height-y-10,width:x2-x+2,height:12,color:white});
    // Súradnice vychádzajú z typografických obdĺžnikov pôvodného PDF.
    // Štvorček pracovného úrazu je na strane 1 v x=226,6–233,3; druhý x=258,0–264,6.
    const square=d.eventType==='choroba_z_povolania'?[259.1,188.0]:[227.7,175.3];
    const [left,top]=square, side=4.6;
    P.drawLine({start:{x:left,y:H-top},end:{x:left+side,y:H-(top+side)},thickness:1.1,color:black});
    P.drawLine({start:{x:left,y:H-(top+side)},end:{x:left+side,y:H-top},thickness:1.1,color:black});
    // Odpoveď č. 3 – preškrtnúť iba neplatnú z možností ÁNO – NIE.
    // Slová vo východiskovom PDF: ÁNO x=299.43–318.92, NIE x=328.95–343.94, y=254.41–264.45.
    const cross=d.salaryLedger==='ANO'?[328.5,344.1]:[298.9,319.3];
    P.drawLine({start:{x:cross[0],y:H-260.4},end:{x:cross[1],y:H-260.4},thickness:0.9,color:black});
    W(0,'ico',259,219,66,1,8);W(0,'nace',437,219,74,1,8);
    W(0,'employer',311,241,207,1,7.6);
    W(0,'salaryOffice',155,300,360,1,8);
    W(0,'date',376,338,59,1,7);W(0,'time',451,338,40,1,7);
    W(0,'place',98,401,415,1,8);W(0,'employee',299,420,214,1,8);
    W(0,'address',263,441,249,1,8);W(0,'birth',282,482,230,1,8);
    W(0,'social',414,503,101,1,7);W(0,'position',317,524,196,1,8);
    W(0,'incomeComp',98,593,415,1,8);
    W(0,'description',98,650,418,7,8);
    W(1,'intent',338,87,175,1,8);W(1,'alcohol',98,130,415,1,8);
    W(1,'breach',169,172,345,1,8);W(1,'discipline',98,215,415,1,8);
    W(1,'investigator',98,248,415,1,8);
    W(1,'recognized',447,275,68,1,8);W(1,'injury',283,291,230,1,8);
    W(1,'deathDate',374,307,140,1,8);W(1,'employeeFaultPercent',283,378,230,1,8);
    W(1,'employeeFault',98,422,414,1,8);W(1,'court',242,533,238,1,8);
    W(1,'courtDecision',250,569,265,1,8);
    const bytes=await pdf.save();
    if(preview){officialShowPreview(bytes,'opu');return;}
    officialBlobDownload(bytes,'Oznamenie_poistnej_udalosti_'+(d.date||'bez_datumu')+'.pdf','application/pdf');
  }
  const pdfBefore=officialPDF;
  officialPDF=async function(kind,preview=false){
    if(kind==='opu')return opuExactPDF(preview);
    return pdfBefore(kind,preview);
  };

  // Word: originálna DOCX predloha; žiadne dopisovanie X za štvorček.
  // Font vložených údajov sa zjednotí medzi oboma dokumentmi na DejaVu Sans Bold
  // pri ponechaní pôvodnej veľkosti a rozloženia zvolenej predlohy.
  function styleSlotRun(run){
    const tag='<w:rFonts w:ascii="DejaVu Sans" w:hAnsi="DejaVu Sans" w:eastAsia="DejaVu Sans" w:cs="DejaVu Sans"/><w:b/>';
    if(/<w:rPr\b/.test(run))return run.replace(/<w:rPr([^>]*)>/,(m,attr)=>'<w:rPr'+attr+'>'+tag);
    return run.replace(/<w:r\b([^>]*)>/,(m,attr)=>'<w:r'+attr+'><w:rPr>'+tag+'</w:rPr>');
  }
  function strikeWrongWord(xml,want){
    // Pracovať len v odseku 3, ktorý obsahuje osobitný placeholder salaryYes.
    return xml.replace(/<w:p\b[^>]*>[\s\S]*?<\/w:p>/g,function(paragraph){
      if(!paragraph.includes('⟦salaryYes⟧'))return paragraph;
      return paragraph.replace(/<w:r\b[^>]*>[\s\S]*?<\/w:r>/g,function(run){
        const tx=[...run.matchAll(/<w:t(?:\s[^>]*)?>([\s\S]*?)<\/w:t>/g)].map(m=>m[1]).join('');
        if(!tx)return run;
        // Odpoveď má vo vzore oddelené behy ÁNO a NIE.
        const strike=(want==='ANO'&&/^NIE\s*$/.test(tx))||(want==='NIE'&&/^\s*ÁNO\s*$/.test(tx));
        if(!strike)return run;
        if(/<w:rPr\b/.test(run))return run.replace(/<w:rPr([^>]*)>/,(m,attr)=>'<w:rPr'+attr+'><w:strike/>');
        return run.replace(/<w:r\b([^>]*)>/,(m,attr)=>'<w:r'+attr+'><w:rPr><w:strike/></w:rPr>');
      });
    });
  }
  const wordBefore=officialWord;
  officialWord=async function(kind){
    const d=officialData();
    if(kind==='opu'&&!['ANO','NIE'].includes(d.salaryLedger))throw Error('V základných údajoch vyber, kto vedie evidenciu miezd (ÁNO/NIE).');
    const data=officialBase64Bytes(kind==='rpu'?BOZP_OFFICIAL.RPU_DOCX:BOZP_OFFICIAL.OPU_DOCX);
    const zip=await JSZip.loadAsync(data),part='word/document.xml';
    let xml=await zip.file(part).async('string');
    if(kind==='opu'){
      // Vyplniť grafické štvorčeky (☒ / ☐) bez zmeny znenia úradného tlačiva.
      const injury=d.eventType!=='choroba_z_povolania';
      xml=xml.replace('pracovný úraz □','pracovný úraz '+(injury?'☒':'☐'));
      xml=xml.replace(/(choroba z(?:\s|\u00a0)povolania )□/,'$1'+(injury?'☐':'☒'));
      xml=strikeWrongWord(xml,d.salaryLedger);
    }
    xml=xml.replace(/<w:r\b[^>]*>[\s\S]*?<\/w:r>/g,run=>/⟦[A-Za-z][A-Za-z0-9]*⟧/.test(run)?styleSlotRun(run):run);
    xml=xml.replace(/⟦([A-Za-z][A-Za-z0-9]*)⟧/g,(match,key)=>officialXmlEsc(d[key]??''));
    if(kind==='opu'){
      // Pôvodná Word predloha má medzi odsekmi vo formulárovej tabuľke
      // 120 twipov pred každým riadkom. Po vyplnení spôsobovali nadbytočnú
      // tretiu stránku. Zníženie len tejto medzery zachová obsah/tabuľky.
      xml=xml.replace(/<w:tbl\b[^>]*>[\s\S]*?<\/w:tbl>/g,partOfTable=>
        partOfTable.replace(/(<w:spacing\b[^>]*\bw:before=")120("[^>]*\/>)/g,(_m,a,b)=>a+'0'+b));
    }
    zip.file(part,xml);
    const out=await zip.generateAsync({type:'uint8array',compression:'DEFLATE'});
    officialBlobDownload(out,(kind==='rpu'?'Zaznam_RPU':'Oznamenie_poistnej_udalosti')+'_'+(d.date||'bez_datumu')+'.docx','application/vnd.openxmlformats-officedocument.wordprocessingml.document');
  };

  // Prevent accidental final export without the decision being set. Data are never guessed.
  const exportBefore=officialExport;
  officialExport=async function(kind,format){
    if(kind==='opu'&&!['ANO','NIE'].includes(String((currentAccident()||{}).salaryLedger||''))){
      alert('Najprv v prvom kroku vyšetrovacieho hárku zvoľ ÁNO alebo NIE pri evidencii miezd.');
      return;
    }
    return exportBefore(kind,format);
  };
})();


/* Export cez obrázky strán bol odstránený. Namiesto neho sa používa pôvodná editovateľná DOCX šablóna. */

// Rýchle nastavenie oboch údajov OPU pri náhľade / stiahnutí.
(function(){
 const original=officialExport;
 officialExport=async function(kind,format){
   if(kind==='opu'){
     const e=currentAccident()||{};
     if(!['ANO','NIE'].includes(String(e.salaryLedger||''))){
       alert('V prvom kroku vyšetrovacieho hárku zvoľ ÁNO alebo NIE pri evidencii miezd.');
       document.getElementById('ai_salaryLedger')?.focus();return;
     }
   }
   try {return await original(kind,format)}
   catch(error){console.error(error);alert('Export sa nepodaril: '+(error?.message||error));}
 };
})();



/* Editovateľný Word z pôvodnej DOCX šablóny, bez snímok PDF alebo obrazových strán. */
const BOZP_NATIVE_EDITABLE_WORD={rpu:'',opu:''};
function bozpWordCleanDate(s){return String(s??'').replace(/[^0-9]/g,'')}
function bozpWordPlaceholders(kind){
 const a=currentAccident()||{},c=company()||{},d=officialData();
 const get=k=>String(a[k]??d[k]??'').trim();
 const [years,months,days]=rpuDuration(a),[shiftStart,shiftEnd]=rpuSplitShift(a);
 const yearDate=k=>rpuISODate(a[k]||d[k]||'');
 const monthBirth=yearDate('birth');
 const h=String(a.time||'').match(/^\s*(\d{1,2})(?::\d{2})?\s*$/);
 const serious=get('serious').toLocaleLowerCase('sk-SK');
 const fatalYN=serious.includes('smrteľ')?'ÁNO':'NIE';
 const severeYN=serious.includes('ťaž')?'ÁNO':'NIE';
 const age=get('age')||rpuAge(a.birth,a.date);
 const val={...d,...a,
  employer:[c.name,c.address].filter(Boolean).join(', '),
  site:get('site')||String(c.site||c.address||''),
  ico:get('ico')||String(c.ico||c.icoNumber||c.companyIco||''),
  birth:monthBirth, date:yearDate('date'), deathDate:yearDate('deathDate'),
  training:yearDate('training'), investigationDate:yearDate('investigationDate'),
  recordDate:yearDate('recordDate'), checkDate:yearDate('checkDate'),
  technicalDue:yearDate('technicalDue'), organizationalDue:yearDate('organizationalDue'),
  educationalDue:yearDate('educationalDue'),
  responsibility:get('responsibility'),
  years, months, days, durationYears:years, durationMonths:months,durationDays:days,
  shiftStart, shiftEnd, hour:h?h[1].padStart(2,'0'):'',
  nationality:get('nationality'), wageBase:get('wageBase'), age,
  nace:get('nace'), source:get('source')||accidentCodeLabel('sourceCode',get('sourceCode')),
  cause:get('cause')||accidentCodeLabel('causeCode',get('causeCode')),
  fatalYN,severeYN, employee:get('employee'),
  position:get('position')||accidentCodeLabel('occupationCode',get('occupationCode')),
  workDuration:[years,months,days].filter(Boolean).join(' / '),
  accidentNumber:get('accidentNumber'),
  incomeComp:get('incomeComp'),
  dateTime:[get('date'),get('time')].filter(Boolean).join(' / '),
  eventType:get('eventType')||'pracovny_uraz',salaryLedger:get('salaryLedger'),
  injury:get('injury')||accidentCodeLabel('injuryCode',get('injuryCode')),
  employeeFaultPercent:d.employeeFaultPercent||'',
  injuryTick:'',salaryYes:''
 };
 // Document output: human-readable dates, no trailing placeholder text, original field formatting.
 const displayDate=v=>{
   const raw=String(v||'').trim();
   if(/^\d{8}$/.test(raw))return raw.slice(6,8)+'.'+raw.slice(4,6)+'.'+raw.slice(0,4);
   const m=raw.match(/^(\d{4})-(\d{2})-(\d{2})$/);
   return m?m[3]+'.'+m[2]+'.'+m[1]:raw;
 };
 Object.assign(val,{
   accidentDateFormatted:displayDate(val.date),birthFormatted:displayDate(val.birth),
   deathDateFormatted:displayDate(val.deathDate),
   signatureDateFormatted:displayDate(val.recordDate||val.date),
   signaturePlace:get('signaturePlace')||String(c.city||''),
   salaryOffice:get('salaryOffice'),
   phoneEmail:get('phoneEmail')||get('contactPhone')||'',
   time:get('time'),
 });
 return val;
}
function bozpWordChoice(xml,key,answer){
 const correct=String(answer||'').toUpperCase().startsWith('ÁNO')?'ÁNO':'NIE';
 const pattern=new RegExp('<w:r\\b[^>]*>(?:(?!<\\/w:r>)[\\s\\S])*?⟦'+key+'⟧(?:(?!<\\/w:r>)[\\s\\S])*?<\\/w:r>');
 const run=(txt,strike)=>'<w:r><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial"/><w:b/><w:sz w:val="13"/>'+(strike?'<w:strike/>':'')+'</w:rPr><w:t>'+txt+'</w:t></w:r>';
 return xml.replace(pattern,run('ÁNO',correct!=='ÁNO')+run(' – ',false)+run('NIE',correct!=='NIE'));
}
function bozpWordStrikeSalary(xml,option,key='salaryYes'){
 return xml.replace(/<w:p\b[^>]*>[\s\S]*?<\/w:p>/g,p=>{
   if(!p.includes('⟦'+key+'⟧'))return p;
   return p.replace(/<w:r\b[^>]*>[\s\S]*?<\/w:r>/g,run=>{
     const str=[...run.matchAll(/<w:t(?:\s[^>]*)?>([\s\S]*?)<\/w:t>/g)].map(m=>m[1]).join('').trim();
     if(!((option==='ANO'&&str==='NIE')||(option==='NIE'&&str==='ÁNO')))return run;
     if(/<w:rPr\b/.test(run))return run.replace(/<w:rPr([^>]*)>/,(_m,a)=>'<w:rPr'+a+'><w:strike/>');
     return run.replace(/<w:r\b([^>]*)>/,(_m,a)=>'<w:r'+a+'><w:rPr><w:strike/></w:rPr>');
   });
 });
}
async function bozpWordRealEditable(kind){
 if(!window.JSZip)throw Error('Chýba knižnica JSZip pre Word export.');
 const val=bozpWordPlaceholders(kind);
 if(kind==='opu'&&!['ANO','NIE'].includes(String(val.salaryLedger)))throw Error('Najprv vyber ÁNO/NIE pri evidencii miezd.');
 const zip=await JSZip.loadAsync(officialBase64Bytes(BOZP_NATIVE_EDITABLE_WORD[kind]));
 const part='word/document.xml';let xml=await zip.file(part).async('string');
 if(kind==='rpu'){
   ['insured','qualification','health','knowledgeChecked','fatalYN','severeYN'].forEach(k=>{xml=bozpWordChoice(xml,k,val[k]);});
 }else{
   const injury=String(val.eventType)!=='choroba_z_povolania';
   xml=xml.replace(/pracovný úraz □/,'pracovný úraz '+(injury?'☒':'☐'));
   xml=xml.replace(/choroba z povolania □/,'choroba z povolania '+(injury?'☐':'☒'));
   xml=bozpWordStrikeSalary(xml,String(val.salaryLedger));
   xml=bozpWordStrikeSalary(xml,String(val.recognized).toUpperCase().startsWith('ÁNO')?'ANO':'NIE','recognized');
   val.recognized='';
 }
 xml=xml.replace(/⟦([A-Za-z][A-Za-z0-9_]*?)(?:__(\d+))?⟧/g,(_whole,key,idx)=>{
   let value=String(val[key]??'');
   if(idx!==undefined){value=value.replace(/[^0-9A-Za-z]/g,'').toUpperCase();value=value[Number(idx)]||'';}
   // The original RPU instructions prescribe capital block letters.
   if(idx===undefined&&key!=='phoneEmail')value=value.toLocaleUpperCase('sk-SK');
   return officialXmlEsc(value);
 });
 if(xml.includes('⟦'))throw Error('Niektoré polia Word šablóny sa nepodarilo vyplniť.');
 zip.file(part,xml);const bytes=await zip.generateAsync({type:'uint8array',compression:'DEFLATE'});
 officialBlobDownload(bytes,(kind==='rpu'?'Zaznam_RPU':'Oznamenie_poistnej_udalosti')+'_'+(val.date||'bez_datumu')+'_EDITOVATELNY.docx','application/vnd.openxmlformats-officedocument.wordprocessingml.document');
}
officialWord=bozpWordRealEditable;
/* Presnejší názov exportu: text a jednotlivé bunky sú v Worde naozaj editovateľné. */
const bozpNativeOldRender=renderAccidentForm;
renderAccidentForm=function(){
 let h=bozpNativeOldRender();
 return h.replaceAll('Word (rovnaký ako PDF)','Editovateľný Word');
};

